pub async fn set_code_tx(chain_id: u64, delegate_to: Address, wallet: PrivateKeySigner) -> TxEnvelope {
    let authorization = Authorization { chain_id: U256::from(chain_id), address: delegate_to, nonce: 0 };
    let signature = wallet
        .sign_hash_sync(&authorization.signature_hash())
        .expect("could not sign authorization");
    let tx = tx(chain_id, 48100, None, Some(authorization.into_signed(signature)), 0, Some(20e9 as u128));
    Self::sign_tx(wallet, tx).await
}
