// PRIMARY: crates/ethereum/payload/src/validator.rs:ensure_well_formed_payload (lines 66-107)
pub fn ensure_well_formed_payload<ChainSpec, T>(chain_spec: ChainSpec, payload: ExecutionData) -> Result<SealedBlock<Block<T>>, PayloadError>
where ChainSpec: EthereumHardforks, T: SignedTransaction,
{
    let ExecutionData { payload, sidecar } = payload;
    let expected_hash = payload.block_hash();
    let sealed_block = payload.try_into_block_with_sidecar(&sidecar)?.seal_slow();
    if expected_hash != sealed_block.hash() {
        return Err(PayloadError::BlockHash { execution: sealed_block.hash(), consensus: expected_hash })
    }
    shanghai::ensure_well_formed_fields(sealed_block.body(), chain_spec.is_shanghai_active_at_timestamp(sealed_block.timestamp))?;
    cancun::ensure_well_formed_fields(&sealed_block, sidecar.cancun(), chain_spec.is_cancun_active_at_timestamp(sealed_block.timestamp))?;
    prague::ensure_well_formed_fields(sealed_block.body(), sidecar.prague(), chain_spec.is_prague_active_at_timestamp(sealed_block.timestamp))?;
    Ok(sealed_block)
}
// CALLER: crates/ethereum/node/src/engine.rs:EthereumEngineValidator (lines 46-52)
fn ensure_well_formed_payload(&self, payload: ExecutionData) -> Result<RecoveredBlock<Self::Block>, NewPayloadError> {
    let sealed_block = self.inner.ensure_well_formed_payload(payload)?;
    sealed_block.try_recover().map_err(|e| NewPayloadError::Other(e.into()))
}

